"""Stable fail-closed lifecycle error codes."""
EXIT_CODES = {name: code for code, name in enumerate(["LIFECYCLE_REGISTRY_INVALID", "PACKAGE_IMPORT_INVALID", "PACKAGE_VERSION_CONFLICT", "SEMANTIC_DIFF_FAILED", "VERSION_POLICY_VIOLATION", "IMPACT_ANALYSIS_INCOMPLETE", "REGRESSION_FAILED", "RELEASE_CANDIDATE_INVALID", "RELEASE_REVIEW_INCOMPLETE", "RELEASE_PUBLICATION_BLOCKED", "ENVIRONMENT_INVALID", "ACTIVATION_BLOCKED", "LIFECYCLE_CONCURRENCY_CONFLICT", "ROLLBACK_BLOCKED", "LIFECYCLE_ARTIFACT_TAMPERED", "CONSUMER_MANIFEST_INVALID", "HISTORICAL_PACKAGE_UNSUPPORTED", "REGISTRY_EVENT_CHAIN_INVALID"], 42)}
ALIASES = {"LIFECYCLE_CONTRACT_INVALID":"LIFECYCLE_REGISTRY_INVALID", "LIFECYCLE_PATH_INVALID":"LIFECYCLE_ARTIFACT_TAMPERED", "LIFECYCLE_RESOURCE_LIMIT":"LIFECYCLE_REGISTRY_INVALID", "LIFECYCLE_TRANSACTION_INCOMPLETE":"LIFECYCLE_REGISTRY_INVALID", "LIFECYCLE_ARTIFACT_MISSING":"LIFECYCLE_REGISTRY_INVALID", "LIFECYCLE_ARTIFACT_INVALID":"LIFECYCLE_ARTIFACT_TAMPERED", "LIFECYCLE_IDENTITY_INVALID":"LIFECYCLE_REGISTRY_INVALID", "LIFECYCLE_CONFLICT":"LIFECYCLE_CONCURRENCY_CONFLICT", "LIFECYCLE_CONSUMER_INVALID":"CONSUMER_MANIFEST_INVALID", "LIFECYCLE_REVIEW_INVALID":"RELEASE_REVIEW_INCOMPLETE", "LIFECYCLE_ACTIVATION_NOT_AUTHORIZED":"ACTIVATION_BLOCKED", "LIFECYCLE_RELEASE_NOT_AUTHORIZED":"RELEASE_PUBLICATION_BLOCKED", "PACKAGE_ID_CONTENT_CONFLICT":"PACKAGE_VERSION_CONFLICT", "PACKAGE_VERSION_CONTENT_CONFLICT":"PACKAGE_VERSION_CONFLICT", "VERSION_IRI_CONTENT_CONFLICT":"PACKAGE_VERSION_CONFLICT"}
class LifecycleError(ValueError):
    def __init__(self, code: str, message: str):
        self.code = code; self.exit_code = EXIT_CODES.get(ALIASES.get(code, code), 42); super().__init__(message)
